68	    default boolean hasEmail(Owner owner) {
69	        return owner.getEmail() != null && !owner.getEmail().isBlank();
70	    }
71	
72	    /**
73	     * The owner's membership points. Starting from 0: add 2 when an email address is present, add 1
74	     * when the owner has no namesakes (namesakeCount is 0), add 2 for a household of 3 or more
75	     * members, and add 3 when the owner's tenure exceeds one fiscal year (more than one elapsed
76	     * fiscal year since the registrationDate; the fiscal year starts on 1 July).
77	     *
78	     * <p>The household size is not derived here: it depends on other owners, so it is computed by
79	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerHousehold} before the
80	     * owner reaches this mapper and read from the entity, keeping this a pure transformation.
81	     */
82	    default int membershipPoints(Owner owner) {
83	        int points = 0;
84	        if (hasEmail(owner)) {
85	            points += 2;
86	        }
87	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
88	            points += 1;
89	        }
90	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
91	            points += 2;
92	        }
93	        long tenureFiscalYears = owner.getRegistrationDate() == null ? 0
94	                : FiscalYear.between(owner.getRegistrationDate(), LocalDate.now());
95	        if (tenureFiscalYears > 1) {
96	            points += 3;
97	        }
98	        return points;
99	    }
