103	     * 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
104	     */
105	    default int membershipLevel(Owner owner) {
106	        int points = membershipPoints(owner);
107	        if (points <= 1) {
108	            return 1;
109	        }
110	        if (points <= 3) {
111	            return 2;
112	        }
113	        if (points <= 5) {
114	            return 3;
115	        }
116	        return 4;
