package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner's {@code identityKey} — the one derived key that all duplicate
 * detection is expressed through. The key joins three normalized parts with {@code '|'}:
 *
 * <ol>
 * <li>the telephone in E.164 form (see {@link TelephoneNormalizer}),</li>
 * <li>the email lower-cased, or empty when absent (see {@link EmailNormalizer}), and</li>
 * <li>the {@code householdId}, or empty when the owner does not share a household.</li>
 * </ol>
 *
 * <p>A create is a duplicate — rejected with a 409 — only when its <em>whole</em> key equals an
 * existing owner's. Because the telephone is part of the key, two members of one household (the same
 * {@code householdId}) with different telephones have different keys and are both allowed.
 *
 * <p>Shared by {@link RequireUniqueIdentity} (which rejects a collision) and the owner mapper (which
 * returns the key), so both compute it the same way and cannot drift apart. Public because the mapper
 * lives in another package.
 */
public final class IdentityKey {

    /** The identity key for the given (raw) telephone, email and household id. */
    public static String of(String telephone, String email, String householdId) {
        String tel = TelephoneNormalizer.toE164(telephone);
        if (tel == null) {
            tel = telephone == null ? "" : telephone;
        }
        String em = EmailNormalizer.isBlank(email) ? "" : EmailNormalizer.normalize(email);
        String hh = householdId == null ? "" : householdId;
        return tel + "|" + em + "|" + hh;
    }

    /** The identity key of an existing (persisted) owner. */
    public static String ofOwner(Owner owner) {
        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    private IdentityKey() {
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The duplicate block of the create-owner pipeline: rejects the request with a 409 (via
 * {@code DuplicateIdentityExceptionHandler}) in either of two cases.
 *
 * <ol>
 * <li><b>Household duplicate.</b> The household is now keyed on {@code (lastName, postcode)} through the
 * deterministic {@link HouseholdKey#householdId}, so an existing owner with the same household means the
 * new owner is a second member of it. That is rejected — <em>unless</em> the request sets
 * {@code sharesHousehold}, which bypasses this block so a declared household member may be created.</li>
 * <li><b>Identity duplicate.</b> An exact match on the whole {@link IdentityKey}
 * ({@code telephone|email|householdId}) is always rejected, even for a declared member: it is the same
 * person, not merely the same household.</li>
 * </ol>
 *
 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail}, so the candidate's
 * telephone and email are already normalized. The new owner is not persisted yet, so every match found
 * is another owner.
 */
public class RequireUniqueIdentity {

    public void service(@Val OwnerFieldsDto owner, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String householdId = HouseholdKey.householdId(owner.getLastName(), owner.getPostcode());
        boolean sharesHousehold = Boolean.TRUE.equals(owner.getSharesHousehold());
        String candidate = IdentityKey.of(owner.getTelephone(), owner.getEmail(), householdId);
        for (Owner existing : ownerRepository.findAll()) {
            if (!DuplicateCandidates.isCandidate(existing)) {
                continue; // a soft-deleted owner no longer blocks a duplicate or identity match
            }
            if (candidate.equals(IdentityKey.ofOwner(existing))) {
                throw new DuplicateIdentityException(candidate);
            }
            if (!sharesHousehold && householdId.equals(HouseholdKey.householdId(existing))) {
                throw new DuplicateIdentityException(householdId);
            }
        }
    }
}

